Q: How to detect which files were conflict-resolved in a git merge commit? A: <p>merge_report.py</p>
<pre><code># ===========================================================
# EMAIL BODIES
# ===========================================================

FONT_STACK = &quot;-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif&quot;
MONO_STACK = &quot;SFMono-Regular,Consolas,'Liberation Mono',Menlo,monospace&quot;

INK = &quot;#1f2933&quot;      # primary text
MUTED = &quot;#6b7280&quot;    # labels, secondary text
LINE = &quot;#e5e7eb&quot;     # hairline borders
PAGE_BG = &quot;#eef1f5&quot;  # area around the card
SOFT_BG = &quot;#f9fafb&quot;  # inset panels
LINK = &quot;#2563eb&quot;

STATUS_STYLES = {
    &quot;Conflict&quot;: {&quot;accent&quot;: &quot;#c2410c&quot;, &quot;soft&quot;: &quot;#fff7ed&quot;, &quot;edge&quot;: &quot;#fdba74&quot;},
    &quot;Merged&quot;: {&quot;accent&quot;: &quot;#15803d&quot;, &quot;soft&quot;: &quot;#f0fdf4&quot;, &quot;edge&quot;: &quot;#86efac&quot;},
    &quot;Error&quot;: {&quot;accent&quot;: &quot;#b91c1c&quot;, &quot;soft&quot;: &quot;#fef2f2&quot;, &quot;edge&quot;: &quot;#fca5a5&quot;},
}


def status_style(status):
    return STATUS_STYLES.get(status, STATUS_STYLES[&quot;Merged&quot;])


def pill(status):
    &quot;&quot;&quot;Small rounded status badge.&quot;&quot;&quot;
    s = status_style(status)
    return (
        f'&lt;span style=&quot;display:inline-block;padding:5px 14px;border-radius:999px;'
        f'background:{s[&quot;soft&quot;]};border:1px solid {s[&quot;edge&quot;]};color:{s[&quot;accent&quot;]};'
        f'font-family:{FONT_STACK};font-size:12px;font-weight:600;'
        f'letter-spacing:.03em&quot;&gt;{esc(status)}&lt;/span&gt;'
    )


def mono(text):
    return f'&lt;span style=&quot;font-family:{MONO_STACK};font-size:13px&quot;&gt;{esc(text)}&lt;/span&gt;'


def build_detail_table(pairs):
    &quot;&quot;&quot;Label / value rows. Values are trusted HTML -- callers escape.&quot;&quot;&quot;
    rows = &quot;&quot;
    for label, value in pairs:
        rows += (
            f'&lt;tr&gt;'
            f'&lt;td valign=&quot;top&quot; style=&quot;padding:9px 0;border-bottom:1px solid {LINE};'
            f'color:{MUTED};font-size:13px;width:140px;white-space:nowrap&quot;&gt;{esc(label)}&lt;/td&gt;'
            f'&lt;td valign=&quot;top&quot; style=&quot;padding:9px 0 9px 16px;border-bottom:1px solid {LINE};'
            f'color:{INK};font-size:13px;word-break:break-word&quot;&gt;{value}&lt;/td&gt;'
            f'&lt;/tr&gt;'
        )
    return f'&lt;table width=&quot;100%&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; border=&quot;0&quot;&gt;{rows}&lt;/table&gt;'


def build_branch_flow(src_branch, src_tip, dest_branch, dest_tip):
    &quot;&quot;&quot;The 'from -&gt; into' pair, shown as two panels either side of an arrow.&quot;&quot;&quot;
    def side(label, branch, tip):
        return (
            f'&lt;td width=&quot;46%&quot; valign=&quot;top&quot; style=&quot;background:{SOFT_BG};'
            f'border:1px solid {LINE};border-radius:8px;padding:12px 14px&quot;&gt;'
            f'&lt;div style=&quot;font-size:11px;letter-spacing:.06em;text-transform:uppercase;'
            f'color:{MUTED};padding-bottom:6px&quot;&gt;{esc(label)}&lt;/div&gt;'
            f'&lt;div style=&quot;font-family:{MONO_STACK};font-size:14px;font-weight:600;'
            f'color:{INK};word-break:break-all&quot;&gt;{esc(branch)}&lt;/div&gt;'
            f'&lt;div style=&quot;font-family:{MONO_STACK};font-size:11px;color:{MUTED};'
            f'padding-top:6px;word-break:break-all&quot;&gt;{esc(tip or &quot;-&quot;)}&lt;/div&gt;'
            f'&lt;/td&gt;'
        )

    return (
        f'&lt;table width=&quot;100%&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; border=&quot;0&quot;&gt;&lt;tr&gt;'
        f'{side(&quot;Merged from&quot;, src_branch, src_tip)}'
        f'&lt;td width=&quot;8%&quot; align=&quot;center&quot; style=&quot;font-size:22px;color:{MUTED}&quot;&gt;&amp;rarr;&lt;/td&gt;'
        f'{side(&quot;Merged into&quot;, dest_branch, dest_tip)}'
        f'&lt;/tr&gt;&lt;/table&gt;'
    )


def build_authors_block(author_files):
    &quot;&quot;&quot;Each author, their email, and the files they are responsible for.&quot;&quot;&quot;
    if not author_files:
        return (
            f'&lt;span style=&quot;color:{MUTED};font-size:13px&quot;&gt;'
            f'No files needed hand-resolving in this merge.&lt;/span&gt;'
        )

    blocks = []
    for author, files in author_files.items():
        name, mail = split_author(author)
        mail_html = (
            f'&lt;a href=&quot;mailto:{esc(mail)}&quot; style=&quot;color:{LINK};text-decoration:none;'
            f'font-size:12px&quot;&gt;{esc(mail)}&lt;/a&gt;'
        ) if mail else &quot;&quot;
        files_html = &quot;&quot;.join(
            f'&lt;div style=&quot;font-family:{MONO_STACK};font-size:12px;color:{INK};'
            f'padding:4px 0 4px 12px;margin-top:4px;border-left:2px solid {LINE};'
            f'word-break:break-all&quot;&gt;{esc(path)}&lt;/div&gt;'
            for path in files
        )
        blocks.append(
            f'&lt;div style=&quot;padding:10px 0&quot;&gt;'
            f'&lt;div style=&quot;font-size:13px;font-weight:600;color:{INK}&quot;&gt;{esc(name)}&lt;/div&gt;'
            f'{mail_html}{files_html}&lt;/div&gt;'
        )
    return &quot;&quot;.join(blocks)


def section_heading(text):
    return (
        f'&lt;div style=&quot;font-size:11px;letter-spacing:.08em;text-transform:uppercase;'
        f'color:{MUTED};font-weight:600;padding:26px 0 10px&quot;&gt;{esc(text)}&lt;/div&gt;'
    )


def build_merge_email(to_name, repo_name, repo_url, src_branch, dest_branch,
                      sha, subject, merger, committer, when, author_files,
                      status, details, src_tip=&quot;&quot;, dest_tip=&quot;&quot;, seen_on=&quot;&quot;):
    &quot;&quot;&quot;Per-merge notification sent to the merger and the file authors.&quot;&quot;&quot;
    s = status_style(status)

    detail_pairs = [
        (&quot;Repository&quot;, esc(repo_name)),
        (&quot;Repo URL&quot;, esc(redact(repo_url))),
        (&quot;Merge commit&quot;, mono(sha)),
        (&quot;Subject&quot;, esc(subject)),
        (&quot;Merged by&quot;, esc(merger)),
    ]
    if committer and committer != merger:
        detail_pairs.append((&quot;Committed by&quot;, esc(committer)))
    detail_pairs.append((&quot;Merged at&quot;, esc(when)))
    if seen_on and seen_on != dest_branch:
        detail_pairs.append((&quot;Seen on&quot;, mono(f&quot;origin/{seen_on}&quot;)))

    return f&quot;&quot;&quot;
&lt;body style=&quot;margin:0;padding:0;background:{PAGE_BG}&quot;&gt;
&lt;table width=&quot;100%&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; border=&quot;0&quot;
       style=&quot;background:{PAGE_BG};padding:24px 12px&quot;&gt;
&lt;tr&gt;&lt;td align=&quot;center&quot;&gt;

  &lt;table width=&quot;640&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; border=&quot;0&quot;
         style=&quot;max-width:640px;background:#ffffff;border:1px solid {LINE};
                border-radius:12px;overflow:hidden;font-family:{FONT_STACK}&quot;&gt;

    &lt;tr&gt;&lt;td style=&quot;height:4px;background:{s['accent']};line-height:4px;font-size:0&quot;&gt;&amp;nbsp;&lt;/td&gt;&lt;/tr&gt;

    &lt;tr&gt;&lt;td style=&quot;padding:26px 30px 0&quot;&gt;
      &lt;div style=&quot;font-size:11px;letter-spacing:.08em;text-transform:uppercase;
                  color:{MUTED};font-weight:600&quot;&gt;{esc(repo_name)}&lt;/div&gt;
      &lt;div style=&quot;font-family:{MONO_STACK};font-size:19px;font-weight:700;color:{INK};
                  padding:8px 0 14px;word-break:break-all&quot;&gt;
        {esc(src_branch)} &lt;span style=&quot;color:{MUTED}&quot;&gt;&amp;rarr;&lt;/span&gt; {esc(dest_branch)}
      &lt;/div&gt;
      {pill(status)}
      &lt;span style=&quot;font-size:13px;color:{MUTED};padding-left:8px&quot;&gt;{esc(details)}&lt;/span&gt;
    &lt;/td&gt;&lt;/tr&gt;

    &lt;tr&gt;&lt;td style=&quot;padding:22px 30px 0;font-size:14px;color:{INK};line-height:1.6&quot;&gt;
      Hello {esc(to_name)},&lt;br&gt;
      a merge was detected in &lt;b&gt;{esc(repo_name)}&lt;/b&gt;
      {'that needed files to be resolved by hand.' if status == 'Conflict' else 'that involves your work.'}
    &lt;/td&gt;&lt;/tr&gt;

    &lt;tr&gt;&lt;td style=&quot;padding:0 30px&quot;&gt;
      {section_heading('Branch detail')}
      {build_branch_flow(src_branch, src_tip, dest_branch, dest_tip)}

      {section_heading('Merge detail')}
      {build_detail_table(detail_pairs)}

      {section_heading('Conflict detail')}
      {build_authors_block(author_files)}
    &lt;/td&gt;&lt;/tr&gt;

    &lt;tr&gt;&lt;td style=&quot;padding:26px 30px 28px&quot;&gt;
      &lt;div style=&quot;background:{SOFT_BG};border:1px solid {LINE};border-radius:8px;
                  padding:14px 16px;font-size:12px;color:{MUTED};line-height:1.7&quot;&gt;
        &lt;b style=&quot;color:{INK}&quot;&gt;Auth detail&lt;/b&gt;&lt;br&gt;
        Report generated by: {esc(REPORTER_NAME)} &amp;lt;{esc(REPORTER_EMAIL)}&amp;gt;&lt;br&gt;
        Git authentication: {esc(AUTH_SUMMARY)}&lt;br&gt;
        Notification sender: {esc(SENDER)}
      &lt;/div&gt;
      &lt;div style=&quot;font-size:11px;color:{MUTED};padding-top:14px;line-height:1.6&quot;&gt;
        Automated read-only report &amp;mdash; this monitor never merges,
        commits or pushes anything.&lt;br&gt;
        Thanks,&lt;br&gt;&lt;b style=&quot;color:{INK}&quot;&gt;DICE&lt;/b&gt;
      &lt;/div&gt;
    &lt;/td&gt;&lt;/tr&gt;

  &lt;/table&gt;

&lt;/td&gt;&lt;/tr&gt;
&lt;/table&gt;
&lt;/body&gt;
&quot;&quot;&quot;


def stat_tile(value, label, color):
    return (
        f'&lt;td width=&quot;30%&quot; align=&quot;center&quot; style=&quot;background:{SOFT_BG};'
        f'border:1px solid {LINE};border-radius:8px;padding:16px 10px&quot;&gt;'
        f'&lt;div style=&quot;font-size:26px;font-weight:700;color:{color};line-height:1&quot;&gt;'
        f'{esc(value)}&lt;/div&gt;'
        f'&lt;div style=&quot;font-size:11px;letter-spacing:.06em;text-transform:uppercase;'
        f'color:{MUTED};padding-top:6px&quot;&gt;{esc(label)}&lt;/div&gt;&lt;/td&gt;'
    )


def build_admin_report(report_rows, started, job_label, scan_errors):
    &quot;&quot;&quot;Full run summary emailed to ADMIN_EMAIL.&quot;&quot;&quot;
    th = (f'padding:10px 12px;background:{SOFT_BG};border-bottom:2px solid {LINE};'
          f'text-align:left;font-size:11px;letter-spacing:.06em;text-transform:uppercase;'
          f'color:{MUTED};font-weight:600;white-space:nowrap')

    rows_html = &quot;&quot;
    for r in report_rows:
        s = status_style(r[&quot;status&quot;])
        td = f'padding:12px;border-bottom:1px solid {LINE};font-size:13px;color:{INK};vertical-align:top'

        tips = &quot;&quot;
        if r.get(&quot;src_tip&quot;) or r.get(&quot;dest_tip&quot;):
            tips = (
                f'&lt;div style=&quot;font-family:{MONO_STACK};font-size:11px;color:{MUTED};'
                f'padding-top:6px;line-height:1.6&quot;&gt;'
                f'from {esc(r.get(&quot;src_tip&quot;) or &quot;-&quot;)}&lt;br&gt;'
                f'into {esc(r.get(&quot;dest_tip&quot;) or &quot;-&quot;)}&lt;/div&gt;'
            )
        err_html = (
            f'&lt;div style=&quot;font-size:12px;color:{STATUS_STYLES[&quot;Error&quot;][&quot;accent&quot;]};'
            f'word-break:break-word&quot;&gt;{esc(r[&quot;errors&quot;])}&lt;/div&gt;'
        ) if r[&quot;errors&quot;] else f'&lt;span style=&quot;color:{MUTED}&quot;&gt;&amp;mdash;&lt;/span&gt;'

        rows_html += (
            f'&lt;tr&gt;'
            f'&lt;td style=&quot;{td}&quot;&gt;{esc(r[&quot;repo&quot;])}&lt;/td&gt;'
            f'&lt;td style=&quot;{td}&quot;&gt;&lt;span style=&quot;font-family:{MONO_STACK};font-size:12px;'
            f'font-weight:600;word-break:break-all&quot;&gt;{esc(r[&quot;src&quot;])} &amp;rarr; '
            f'{esc(r[&quot;dest&quot;])}&lt;/span&gt;{tips}&lt;/td&gt;'
            f'&lt;td style=&quot;{td}&quot;&gt;{pill(r[&quot;status&quot;])}&lt;/td&gt;'
            f'&lt;td style=&quot;{td}&quot;&gt;{esc(r[&quot;details&quot;])}&lt;/td&gt;'
            f'&lt;td style=&quot;{td};word-break:break-word&quot;&gt;{esc(r[&quot;merged_by&quot;])}&lt;/td&gt;'
            f'&lt;td style=&quot;{td}&quot;&gt;{build_authors_block(r[&quot;author_files&quot;])}&lt;/td&gt;'
            f'&lt;td style=&quot;{td}&quot;&gt;{err_html}&lt;/td&gt;'
            f'&lt;/tr&gt;'
        )

    if not report_rows:
        rows_html = (
            f'&lt;tr&gt;&lt;td colspan=&quot;7&quot; style=&quot;padding:28px 12px;text-align:center;'
            f'color:{MUTED};font-size:13px&quot;&gt;No new merges detected in this run.&lt;/td&gt;&lt;/tr&gt;'
        )

    counts = defaultdict(int)
    for r in report_rows:
        counts[r[&quot;status&quot;]] += 1

    errors_html = &quot;&quot;
    if scan_errors:
        items = &quot;&quot;.join(
            f'&lt;div style=&quot;font-family:{MONO_STACK};font-size:12px;color:{INK};'
            f'padding:8px 0;border-bottom:1px solid {LINE};white-space:pre-wrap;'
            f'word-break:break-word&quot;&gt;{esc(e)}&lt;/div&gt;'
            for e in scan_errors
        )
        errors_html = (
            f'&lt;div style=&quot;background:{STATUS_STYLES[&quot;Error&quot;][&quot;soft&quot;]};'
            f'border:1px solid {STATUS_STYLES[&quot;Error&quot;][&quot;edge&quot;]};border-radius:8px;'
            f'padding:14px 16px;margin-bottom:8px&quot;&gt;'
            f'&lt;div style=&quot;font-size:13px;font-weight:600;'
            f'color:{STATUS_STYLES[&quot;Error&quot;][&quot;accent&quot;]};padding-bottom:4px&quot;&gt;'
            f'Scan errors&lt;/div&gt;{items}&lt;/div&gt;'
        )

    config_pairs = [
        (&quot;Merges from&quot;, esc(describe_patterns(SOURCE_BRANCHES))),
        (&quot;Merges into&quot;, esc(describe_patterns(DEST_BRANCHES))),
        (&quot;Look-back&quot;, esc(f&quot;{AUDIT_SINCE_DAYS} day(s); already-reported merges suppressed&quot;)),
        (&quot;Git auth&quot;, esc(AUTH_SUMMARY)),
        (&quot;Sender&quot;, esc(SENDER)),
    ]

    merge_date = started.strftime(&quot;%Y/%m/%d %H:%M&quot;)

    dry_banner = (
        f'&lt;div style=&quot;background:#fffbeb;border:1px solid #fcd34d;border-radius:8px;'
        f'padding:12px 16px;margin-bottom:18px;font-size:13px;color:#92400e&quot;&gt;'
        f'&lt;b&gt;Dry run&lt;/b&gt; &amp;mdash; no emails were sent to mergers or authors.&lt;/div&gt;'
    ) if DRY_RUN else &quot;&quot;

    return merge_date, f&quot;&quot;&quot;
&lt;body style=&quot;margin:0;padding:0;background:{PAGE_BG}&quot;&gt;
&lt;table width=&quot;100%&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; border=&quot;0&quot;
       style=&quot;background:{PAGE_BG};padding:24px 12px&quot;&gt;
&lt;tr&gt;&lt;td align=&quot;center&quot;&gt;

  &lt;table width=&quot;900&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; border=&quot;0&quot;
         style=&quot;max-width:900px;background:#ffffff;border:1px solid {LINE};
                border-radius:12px;overflow:hidden;font-family:{FONT_STACK}&quot;&gt;

    &lt;tr&gt;&lt;td style=&quot;height:4px;background:{INK};line-height:4px;font-size:0&quot;&gt;&amp;nbsp;&lt;/td&gt;&lt;/tr&gt;

    &lt;tr&gt;&lt;td style=&quot;padding:26px 30px 0&quot;&gt;
      &lt;div style=&quot;font-size:20px;font-weight:700;color:{INK}&quot;&gt;Merge Monitor Report&lt;/div&gt;
      &lt;div style=&quot;font-size:13px;color:{MUTED};padding-top:6px&quot;&gt;
        {esc(merge_date)} &amp;nbsp;&amp;middot;&amp;nbsp; {esc(job_label)}
      &lt;/div&gt;
    &lt;/td&gt;&lt;/tr&gt;

    &lt;tr&gt;&lt;td style=&quot;padding:22px 30px 0&quot;&gt;
      {dry_banner}
      &lt;table width=&quot;100%&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; border=&quot;0&quot;&gt;&lt;tr&gt;
        {stat_tile(len(report_rows), 'New merges', INK)}
        &lt;td width=&quot;5%&quot;&gt;&amp;nbsp;&lt;/td&gt;
        {stat_tile(counts['Conflict'], 'With conflicts', STATUS_STYLES['Conflict']['accent'])}
        &lt;td width=&quot;5%&quot;&gt;&amp;nbsp;&lt;/td&gt;
        {stat_tile(counts['Merged'], 'Clean merges', STATUS_STYLES['Merged']['accent'])}
      &lt;/tr&gt;&lt;/table&gt;
    &lt;/td&gt;&lt;/tr&gt;

    &lt;tr&gt;&lt;td style=&quot;padding:0 30px&quot;&gt;
      {section_heading('Scope of this run')}
      {build_detail_table(config_pairs)}
    &lt;/td&gt;&lt;/tr&gt;

    &lt;tr&gt;&lt;td style=&quot;padding:0 30px&quot;&gt;
      {section_heading('Merges detected')}
      {errors_html}
    &lt;/td&gt;&lt;/tr&gt;

    &lt;tr&gt;&lt;td style=&quot;padding:0 30px 4px&quot;&gt;
      &lt;table width=&quot;100%&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; border=&quot;0&quot;
             style=&quot;border:1px solid {LINE};border-radius:8px;border-collapse:separate&quot;&gt;
        &lt;tr&gt;
          &lt;th style=&quot;{th}&quot;&gt;Repo&lt;/th&gt;
          &lt;th style=&quot;{th}&quot;&gt;Branches&lt;/th&gt;
          &lt;th style=&quot;{th}&quot;&gt;Status&lt;/th&gt;
          &lt;th style=&quot;{th}&quot;&gt;Details&lt;/th&gt;
          &lt;th style=&quot;{th}&quot;&gt;Merged by&lt;/th&gt;
          &lt;th style=&quot;{th}&quot;&gt;Authors&lt;/th&gt;
          &lt;th style=&quot;{th}&quot;&gt;Errors&lt;/th&gt;
        &lt;/tr&gt;
        {rows_html}
      &lt;/table&gt;
    &lt;/td&gt;&lt;/tr&gt;

    &lt;tr&gt;&lt;td style=&quot;padding:22px 30px 28px;font-size:11px;color:{MUTED};line-height:1.6&quot;&gt;
      Read-only monitor &amp;mdash; no merges, commits or pushes are performed
      by this script.
    &lt;/td&gt;&lt;/tr&gt;

  &lt;/table&gt;

&lt;/td&gt;&lt;/tr&gt;
&lt;/table&gt;
&lt;/body&gt;
&quot;&quot;&quot;


# ===========================================================
# MAIN JOB
# ===========================================================

def run_monitor(job_label=&quot;Manual run&quot;):
    started = datetime.now()
    print(f&quot;[{started:%Y-%m-%d %H:%M:%S}] Merge scan starting ({job_label})...&quot;)

    if not os.path.exists(REPOS_FILE):
        print(f&quot;Repos file not found: {REPOS_FILE}&quot;)
        return

    with open(REPOS_FILE, encoding=&quot;utf-8&quot;) as f:
        repos = [
            line.strip() for line in f
            if line.strip() and not line.strip().startswith(&quot;#&quot;)
        ]

    report_rows = []
    scan_errors = []
    state = load_state()

    workdir = tempfile.mkdtemp(prefix=&quot;merge_monitor_&quot;)
    try:
        for repo_url in repos:
            repo_name = repo_display_name(repo_url)
            try:
                repo_path = clone_repo(repo_url, workdir)
                scan_repo(repo_url, repo_path, repo_name, state, report_rows)
            except Exception as e:
                err = redact(f&quot;{repo_name}: {e}\n{traceback.format_exc()}&quot;)
                print(f&quot;ERROR: {err}&quot;)
                scan_errors.append(err)
    finally:
        shutil.rmtree(workdir, ignore_errors=True)
        if not DRY_RUN:
            save_state(state)

    merge_date, html_report = build_admin_report(
        report_rows, started, job_label, scan_errors
    )
    send_email_safe(
        ADMIN_EMAIL, f&quot;Merge Monitor Report - {merge_date}&quot;, html_report, is_html=True
    )

    print(f&quot;Scan complete ({job_label}). {len(report_rows)} new merge(s) found. &quot;
          f&quot;Report emailed to {ADMIN_EMAIL}.&quot;)


def run_monitor_guarded(job_label):
    &quot;&quot;&quot;Scheduler wrapper: a failing run must never kill the weekly loop.&quot;&quot;&quot;
    try:
        run_monitor(job_label=job_label)
    except Exception as e:
        err = redact(str(e) + &quot;\n&quot; + traceback.format_exc())
        print(f&quot;ERROR: scheduled run failed:\n{err}&quot;)
        send_email_safe(ADMIN_EMAIL, &quot;[Error] Scheduled merge scan failed&quot;, err)


# ===========================================================
# ENTRY POINT / SCHEDULING
# ===========================================================

def main():
    parser = argparse.ArgumentParser(
        description=&quot;Read-only merge monitor &amp; conflict reporter&quot;
    )
    parser.add_argument(
        &quot;--run-now&quot;, action=&quot;store_true&quot;,
        help=&quot;Scan immediately once, then exit (ignores RUN_MODE=scheduler).&quot;
    )
    parser.add_argument(
        &quot;--dry-run&quot;, action=&quot;store_true&quot;,
        help=&quot;Scan and print what would be emailed, but send nothing.&quot;
    )
    args = parser.parse_args()

    global DRY_RUN
    if args.dry_run:
        DRY_RUN = True
        print(&quot;DRY RUN enabled via --dry-run&quot;)

    run_mode = os.getenv(&quot;RUN_MODE&quot;, &quot;manual&quot;).lower()

    if args.run_now or run_mode == &quot;manual&quot;:
        run_monitor(job_label=&quot;Manual run&quot;)
        return

    if run_mode == &quot;scheduler&quot;:
        day_method = getattr(schedule.every(), SCHEDULE_DAY, None)
        if day_method is None:
            raise RuntimeError(f&quot;Invalid SCHEDULE_DAY in .env: {SCHEDULE_DAY}&quot;)
        day_method.at(SCHEDULE_TIME).do(
            run_monitor_guarded,
            job_label=f&quot;Scheduled ({SCHEDULE_DAY} {SCHEDULE_TIME})&quot;,
        )

        print(f&quot;Scheduler started. Will scan every {SCHEDULE_DAY} at {SCHEDULE_TIME}.&quot;)
        print(f&quot;Next automatic run: {schedule.next_run()}&quot;)
        print(&quot;Leave this process running (e.g. under systemd/pm2/nohup/NSSM).&quot;)
        print(&quot;To trigger an out-of-schedule scan without stopping this process, &quot;
              &quot;run in another terminal:  python merge_report.py --run-now&quot;)

        last_heartbeat = 0
        while True:
            schedule.run_pending()

            # Hourly heartbeat so the log proves the scheduler is alive
            if time.time() - last_heartbeat &gt; 3600:
                last_heartbeat = time.time()
                print(f&quot;[{datetime.now():%Y-%m-%d %H:%M:%S}] scheduler alive; &quot;
                      f&quot;next run {schedule.next_run()}&quot;)

            time.sleep(30)
    else:
        raise RuntimeError(
            f&quot;Invalid RUN_MODE in .env: {run_mode} (expected 'manual' or 'scheduler')&quot;
        )


if __name__ == &quot;__main__&quot;:
